:root {
    --primary-400               : #2D94FC;

    --neutral-50                : #D5DBE3;
    --neutral-100               : #ABB5C3;
    --neutral-200               : #8290A4;
    --neutral-400               : #546681;
    --neutral-700               : #374957;

    --table-header-color: theme('colors.slate.700');
    --table-header-fontSize: theme('fontSize.sm');
    --table-header-fontWeight: theme('fontWeight.semibold');
    --table-header-backgroundColor: theme('backgroundColor.slate.200');
    --table-header-padding-inline: theme('padding.3');
    --table-header-padding-block: theme('padding.2');
    --table-border-color: theme('borderColor.slate.300');
    --table-data-fontSize: theme('fontSize.sm');
    --table-active-row-background: theme('backgroundColor.slate.400');
    --table-hover-background: #f1f5f9;
    --table-zebra-pattern-background:theme('backgroundColor.slate.400');
    --table-height-for-fixed-header: 350px;
    --table-width-for-fixed-cols: 992px;
}

body {
    @apply bg-blue-50 font-normal;;
    color: var(--neutral-700);
}

ol {@apply ms-5 list-decimal;}


// Hover for breadcrumbs
@media (hover:hover) {
    .breadcrumbs > ul > li > a {
      text-decoration: none;
      &:hover {
        text-decoration: inherit;
      }
    }
  }

@media (max-width: 767px) {
    // .sidebar {
    //     @apply hidden;
    // }
    .wrapper {
        @apply ml-0;
    }
}

// *******  Header ******* //


// *******  Header Rounded Profile ******* //

.profile-img {
    position: relative;
    cursor: pointer;

    .name {
        // background-color: $light-purple;
        background-color: #4F46E5;
        display: flex; 
        align-items: center;
        justify-content: center;
        width: 44px;
        height: 44px;
        border-radius: 50%;
        .letters {
            // color: $dk-purple;
            color: #fff;
            font-weight: 600;
            font-size: 0.875rem;
        }
    }
    img {
        border-radius: 50%;
    }

    .dd-holder {
        opacity: 0;
        height: 0;
        position: absolute;
        z-index: -20;
        right: 0;
        padding: 0.75rem 1.5rem;
        background-color: #fff;
        box-shadow: (0, 16px, 32px, var(--neutral-700));
        transition: height 0.3s ease-out, opacity 0.3s ease-out;
        width: auto;

        &.show {
            opacity: 1;
            height: auto;
            z-index: 20;
        }

        .dd-options {
            list-style: none;
            margin: 0;
            padding: 0;
        }
    }

    .dd-options {
        .dd-item {
            position: relative;
            transition: background-color 0.3s ease-out;

            &::before {
                content: '';
                position: absolute;
                top: -0.5rem;
                right: -1.5rem;
                bottom: -0.5rem;
                left: -1.5rem;
                z-index: -1;
                background-color: transparent;
            }

            &:hover {
                &::before {
                    background-color: hsl(0, 0%, 97%);
                }
            }

            &+.dd-item {
                margin-top: 1rem;
            }

            .dd-link {
                display: flex;
                align-items: center;
                color: var(--neutral-700);
                text-decoration: none;
                font-weight: 450;
                .isax {
                    margin-right: 0.75rem;
                }
            }
        }
    }
}

:root {
    --menu-indent           : 12px;
    --menu-bg-active        : theme('colors.indigo.600');
    --menu-bg-active-hover  : theme('colors.indigo.700');
    --menu-bg-hover         : hsl(210, 40%, 96.1%);

    --menu-title            : theme('colors.indigo.100');
    --menu-title-height     : 54px;
}

.collapsing ~ .cm-content {transition: height 0.4s ease;}

.cm-wrapper {height: calc(100% - 60px); overflow-x: hidden;}
.collapse-menu {
    .cm-holder {display: grid; grid-template-rows: auto 1fr;}
    input[type="radio"] {position: relative; z-index: 50; grid-column-start: 1; grid-row-start: 1; appearance: none; opacity: 0; cursor: pointer;
        &:checked ~ .cm-content {/*max-height: 600px;*/}
        &:hover ~ .cm-title {background-color: var(--menu-bg-hover);
            &.router-link-exact-active {background-color: var(--menu-bg-active-hover);}
        }
        &.active ~ .cm-title {background-color: var(--menu-bg-hover);
            .cm-icon-down {transform: rotate3d(0, 0, 1, -180deg);}
        }

        ~ .cm-title.router-link-exact-active {color: #fff; background-color: var(--menu-bg-active);}
    }
    .cm-holder-link {
        input[type="radio"] {/*pointer-events: none;*/
            // &.active ~ .cm-title {background-color: transparent;}
        }
    }

    .cm-title {position: relative; padding: 12px 36px 12px 15px; display: flex; align-items: center; grid-column-start: 1; grid-row-start: 1; transition: background-color 0.2s ease;
        &:hover {background-color: var(--menu-bg-hover);}
    }
    .cm-content {height: 0; /*max-height: 0;*/ overflow: hidden;/* transition: height 0.4s ease/* max-height 0.4s linear*/;
        .cm-title {padding-left: calc(2 * var(--menu-indent));}
        .cm-content {
            .cm-title {padding-left: calc(3 * var(--menu-indent));}
        }
    }

    .cm-icon {margin-right: 10px; width: 20px; flex-shrink: 0; text-align: center;}
    .cm-icon-down {position: absolute; top: 50%; right: 0; margin-top: -8px; padding: 0 10px; font-size: 16px; line-height: 1; transition: transform 0.2s ease;}
}

@media (min-width: 768px) {
    .sidebar-collapsed {
        .sidebar {overflow: visible;}
        .cm-holder-main {
            input[type="radio"] {
                &:checked {
                    // & ~ .cm-title:after {display: block;}
                    & ~ .cm-content {/*max-height: none;*/ display: block;}
                }
                // &.active ~ .cm-title {color: #fff; background-color: var(--menu-bg-active);}
            }
            > .cm-title {padding: 12px 2px; flex-direction: column;
                .cm-icon {margin-right: 0; margin-bottom: 8px; width: 100%;}
                span {font-size: 12px; line-height: 16px; text-align: center;}
                .cm-icon-down {display: none;}
                // &:after {position: absolute; top: 50%; right: -17px; z-index: 1000; content: ''; margin-top: -5px; width: 0; height: 0; display: none; border: 6px solid; border-color: transparent transparent #fff #fff; box-shadow: -1px 1px 0 0 rgba(60,64,67,.15); transform: rotate3d(0, 0, 1, 45deg);}
            }
            > .cm-content {position: fixed; top: 10px/*calc(var(--header-height) + 10px)*/; bottom: 10px; left: calc(var(--sidebar-width) + 10px); width: 280px; /* max-height: none;*/ height: auto !important; display: none; border-radius: 8px; background-color: #fff; box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.08);
                > .cm-inner-holder {height: calc(100% - var(--menu-title-height)); overflow-x: hidden; overflow-y: auto;}
            }
        }
        .cm-icon-down {right: 5px;}
        .cm-content-title {padding: 5px 20px; height: var(--menu-title-height); display: flex; align-items: center; justify-content: center; background-color: var(--menu-title);}
    }
}

// *******  Buttons  ******* //

.btn-wrapper {@apply mt-6 flex flex-wrap gap-4;
    &.center {@apply justify-center;}
    &.end { @apply justify-end;}
    &-alt { @apply mt-0;}
}

// *******  Common Button Class ******* //

.btn {
    @apply px-7 font-semibold;

    &:disabled {
        @apply opacity-60 text-white;
    }
}


// *******  Solid Buttons ******* //

.btn-solid {
    @apply border-slate-600 text-white bg-slate-600 hover:border-slate-700 hover:bg-slate-700;

    &.btn-main {
        @apply border-indigo-600 bg-indigo-600 hover:border-indigo-700 hover:bg-indigo-700;
    }

    &.btn-danger {
        @apply border-red-600 bg-red-600 hover:border-red-700 hover:bg-red-700;
    }

    &.btn-success {
       @apply border-green-600 bg-green-600 hover:border-green-700 hover:bg-green-700;
    }
}


// *******  Outline Buttons ******* //

.btn-outline {
    @apply border-slate-600 bg-transparent text-slate-600 hover:border-slate-700 hover:bg-slate-700 hover:text-white;

    &.btn-main {
        @apply border-indigo-600 text-indigo-600 hover:border-indigo-700 hover:bg-indigo-700 hover:text-white;
    }
}


// *******  Button Link ******* //

.btn-link {
    @apply px-5 no-underline hover:border-slate-700 hover:bg-slate-700 hover:text-white; 

    &.btn-main {
        @apply  text-indigo-600 hover:border-indigo-700 hover:bg-indigo-700 hover:text-white hover:no-underline;
    }
}

.btn-ghost:hover{
    @apply bg-transparent;
}


// *******  Rounded Action Buttons ******* //

.action-holder {
    @apply mt-4 flex justify-center items-center border rounded-full w-8 h-8 transition-all tooltip;

    &.primary {
        @apply border-indigo-600;

        i {
            @apply text-indigo-600;
        }

        &:hover {
            @apply bg-indigo-600;
        }
    }

    &.danger {
        @apply border-red-600;

        i {
            @apply text-red-600;
        }

        &:hover {
            @apply bg-red-600;
        }
    }

    &:hover {
        @apply cursor-pointer;

        i {
            @apply text-white;
        }
    }

}

// *******  Icons Holder & Classes ******* //

.icon-holder {
    @apply flex gap-6;

    .icon {
        @apply tooltip cursor-pointer text-2xl;

        &.icon-success {
            @apply text-green-600 tooltip-left;
        }

        &.icon-danger {
            @apply text-red-600 tooltip-left;
        }
    }
}

// *******  Box = Card ******* //
.box {
    @apply rounded-lg bg-white p-8 shadow-xl;

    &-title {
        @apply text-lg font-semibold text-slate-700;
    }

    &-steps { 
        @apply p-2 text-center mb-6;
    }

    &-dashboard {
        @apply text-white relative overflow-hidden cursor-pointer 
        before:absolute before:-top-2 before:-right-16
        before:w-36 before:h-36 before:bg-white 
        before:opacity-20 before:rounded-lg
        before:rotate-45 before:transition-transform
        after:absolute after:-top-10 after:-right-16
        after:w-36 after:h-36 after:bg-white 
        after:opacity-20 after:rounded-lg
        after:rotate-45 after:transition-transform
        hover:before:rotate-0
        hover:after:-rotate-45;
        &.green {
            @apply bg-emerald-600;
        }
        &.red {
            @apply bg-rose-500;
        }
        &.indigo {
            @apply bg-indigo-500;
        }
        &.purple {
            @apply bg-purple-600;
        }
        &.cyan {
            @apply bg-cyan-600;
        }
        .icon-holder {
            @apply w-12 h-12 flex flex-row items-center justify-center text-white;
        }
    }
    &-flex {
        @apply flex flex-row items-center justify-between;
    }
    .count {
        @apply text-2xl font-bold text-white;

        &-label {
            @apply text-base font-normal text-white opacity-80;
        }
    }
}

// --------------------------------
// Daisy UI Form
// --------------------------------

.form-flex {
    @apply flex flex-row items-center justify-start gap-7;

     &-alt { 
        @apply justify-between; 

        .btn-wrapper { 
            @apply mt-0;
        }
    }

    &-end {
        @apply items-end
    }
}

.form-grid {
    @apply grid grid-cols-2 gap-7 items-center;

    &-one {
        @apply grid grid-cols-1;
    }

     &-alt { 
        @apply grid-cols-3 items-center;
    }
}


.form-label {
    @apply text-base text-slate-500 cursor-pointer; 

    &.required { 
        &::after {
            content: "*";
            @apply text-red-600 ml-1;
        }
    }
}


.form-text {
    @apply mt-2;
}

.form-control-holder {
    @apply mt-2;
}

.form-control {
    @apply input input-bordered w-full;

     &-alt { 
        @apply w-1/2 ml-auto;
    }
    &-error { 
        @apply input-error;
    }
}

.error-text { 
    @apply text-[13px] text-red-600 mt-1;
}


.file-control {
    --n: theme('colors.secondary');
    --nc: 0 0% 100%;
      @apply file-input file-input-bordered w-full;
    }

.form-helper {
    @apply mt-2 text-sm text-slate-400;
}


// *******  Radio  ******* //

.form-check {
    @apply mt-2 flex gap-4 flex-row items-center;
}

.form-check-label {
    @apply label flex flex-row items-center cursor-pointer justify-start;

    .radio {
        @apply me-2 checked:bg-blue-600;
    }
}

// *******  Radio + Grid Data ******* //

.form-box {
    @apply relative z-10 px-8 py-5 grid grid-cols-[60px_repeat(2,_minmax(0,_1fr))] gap-x-5 gap-y-1 [&_input]:row-span-2 items-center cursor-pointer;

    input {
        @apply checked:bg-blue-600;
        + span::before {
            content: '';
            @apply absolute top-0 bottom-0 left-0 right-0 -z-10 rounded-lg bg-white shadow-xl;
        }
    }

    span {
        @apply text-slate-500;
    }

    strong {
        @apply text-slate-700;
    }

    input:checked + span::before {
        box-shadow: inset 0 0 0 3px rgba(37 99 235 / 20%);
    }
}


// --------------------------------
// FormKit Form CSS START
// --------------------------------

.fk-group {
    @apply relative;
}


// *******  FormKit Error Message ******* //
.fk-messages {
    .fk-message {@apply mt-1 text-sm;
        &-error {@apply text-red-600;}
    }
}


// *******  Radio + Checkbox Labels & Options ******* //

.fk-options-group {
    @apply flex items-center gap-4;
}

.fk-option {
    @apply mt-2;
}

.fk-main-label {
    @apply text-base text-slate-500;
}

.fk-label-text {
    @apply label-text ml-2 ;
}


// *******  Radio SCSS START ******* //

.fk-group[data-type="radio"] {

    .fk-decorator {
        @apply  w-6 h-6 p-2 block rounded-full cursor-pointer border;
        border-color: hsl(var(--bc) / var(--tw-border-opacity));
        --tw-border-opacity: 0.2;

        svg {
            @apply scale-0 transition-transform;

            circle {
                @apply fill-blue-600; 
            }
        }
    }

    // When Radio Is Checked

    [data-checked]  {
        @apply fill-blue-600; 

        .fk-decorator {
            box-shadow: inset 0 0 0 1px #2563eb;
        }

        svg {
            @apply w-full scale-[2] ;

            circle {
                @apply fill-blue-600; 
            }
        }
    }
}
// *******  Radio SCSS END ******* //


// *******  Checkbox SCSS START ******* //

.fk-group[data-type="checkbox"] {

    .fk-decorator {
        @apply  w-6 h-6 block cursor-pointer border rounded-lg bg-white;
        border-color: hsl(var(--bc) / var(--tw-border-opacity));
        --tw-border-opacity: 0.2;

        &:hover {
            border-color: #2563eb;
        }

        .fk-decorator-icon {
            svg {
                display: none;
            }
        }
    }

    // When Checkbox Is Checked

    [data-checked]  {
        @apply fill-blue-600; 

        .fk-decorator {
            @apply bg-blue-600;

            .fk-decorator-icon {
                &::after {
                    content: '\f00c';
                    font-family: 'Font Awesome 6 Pro';
                    color: #fff;
                    position: absolute;
                    top: 0;
                    left: 0;
                    right: 0;
                    bottom: 0;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                }
            }
        }
    }

}

// *******  Checkbox SCSS END ******* //

// *******  INPUT SCSS START ******* //

.fk-group[data-family="text"] {

    .fk-wrapper {
        @apply w-full;
    }

    .fk-inner {
        @apply relative;
    }

    .fk-text-input {
        @apply form-control mt-2;
    }

    .formkit-suffix-icon {
        position: absolute;
        right: 8px;
        top: 50%;
        transform: translate(-50%, -50%);

        svg {
            width: 1rem;
        }
    }
}

// If Invalid Response 

.fk-group[data-family="text"][data-invalid="true"] {

    .fk-text-input {
        @apply input-error;
    }
}


// *******  INPUT SCSS END ******* //


// *******  INPUT Password SCSS START ******* //
.fk-group[data-type="password"] {

    .fk-inner {
        @apply relative;
    }

    .formkit-suffix-icon {
        position: absolute;
        right: 8px;
        top: 50%;
        transform: translate(-50%, -50%);

        svg {
            width: 1rem;
        }
    }
}
// *******  INPUT Password SCSS END ******* //

// *******  INPUT Single File SCSS START ******* //

.fk-group[data-type="file"] {

    .fk-inner {
        @apply relative;

        .fk-file-input {
            @apply file-control mt-2;
            padding-right: 2.5rem
        }

        .fk-file-nofile {
            @apply hidden;
        }

        .fk-file-list-container {
            @apply border rounded-lg p-4;

            .fk-file-list {
                @apply truncate;

            }

            .fk-file-icon  {
                &::after {
                    content: '\f15b';
                    font-family: 'Font Awesome 6 Pro';
                    margin-right: 0.5rem;
                }
            }

            .fk-file-icon {
                svg {
                    @apply hidden;
                }
            }

            .fk-file-name {
                @apply text-sm font-medium;
            }

            .fk-file-removeall {
                @apply block text-xs mt-2 text-blue-600 hover:text-red-600;
            }

            .fk-file-single-remove-icon {
                @apply w-4 h-4;
                position: absolute;
                top: 22%;
                right: 1rem;
                transform: translate(0, -50%);
            }
        }

    }

}

// *******  INPUT Single File SCSS END ******* //



// *******  INPUT Multiple File SCSS START ******* //
.fk-group[data-multiple="true"] {

    .fk-file-removeall {
        @apply text-xs  text-blue-600 hover:text-red-600;
    }
}
// *******  INPUT Multiple File SCSS END ******* //




// *******  Select SCSS START ******* //

.fk-group[data-type="select"] {

    .fk-inner {
        @apply flex items-end gap-4;
    }

    .fk-select-input {
        @apply select select-bordered w-full mt-2;
    }

    .fk-select-icon {
        display: none;
    }
}

// *******  Select SCSS END ******* //


// *******  Textarea SCSS START ******* //

.fk-group[data-type="textarea"] {

    @apply w-full;
    .fk-textarea-input {
        @apply textarea textarea-bordered w-full mt-2;
    }

}

// *******  Textarea SCSS END ******* //
.required { 
    .fk-main-label {
        &::after {
            content: "*";
            @apply text-red-600 ml-1;
        }
    }
}
