        // window.app.config.globalProperties.$toast.add({
        //   severity: "error",
        //   summary: "Error",
        //   detail: "Langauage is not found on cdn! Not able to load that  " + lang + " So setting local lang",
        //   life: 5000,
        // });
        // Fallback to local language file
        return fetchLocalLanguageFile();
      });
  };

  if (!cdnPath || !cdnBucketId) {
    // console.error("CDN path or bucket ID is missing.");
    return fetchLocalLanguageFile();
  }

  return new Promise((resolve, reject) => {

    // console.log("above promiseee lang", lang, !lang)
    if (!lang) {
      lang = i18n.global.locale;
    }
  //  console.log('loaded languages',loadedLanguages)
    if (!loadedLanguages.includes(lang)) {
        // alert("inside promise")
      fetchDynamicLanguageFile(lang)
        .then(() => {
          loadedLanguages.push(lang);
          resolve(lang);
        })
        .catch((error) => {
          // console.error("Error loading language:", error);
          reject(error);
        });
    } else {
      // console.log('Language already loaded:', lang);
      resolve(setI18nLanguage(lang)); // Directly resolve if already loaded
    }
  });
}










