        //   router.push({
        //     name: 'ViewStudentProfile',
        //   })
        // } else
        //  { 
        // rs.showErrorToast("Login")
        // }
        // })

      })
    },

    AUTH_LOGOUT() {
      return new Promise((resolve) => {
        sessionStorage.removeItem('user-token')
        // remove the axios default header
        // delete axios.defaults.headers.common['Authorization']
        router.push({
          name: 'login',
